entries[271045] = { ["name"] = "Instabile Bombe", ["text"] = "40 Meter Reichweite\nSofort 18 sek. Abklingzeit\n1 Aufladung\nSchleudert eine Bombe auf das Ziel, die bei der Explosion in einem kegelförmigen Bereich (78% der Angriffskraft) Feuerschaden verursacht und Gegner mit unbeständigem Lauffeuer bedeckt, das ihnen im Verlauf von 6 Sek. (156% der Angriffskraft) Feuerschaden zufügt. Fügt Zielen über 8 Ziele hinaus verringerten Schaden zu.\n\nFügt Eurem Primärziel 80% mehr Schaden zu.\n\n'Instabile Bombe' reagiert heftig mit Gift und fügt so Zielen, die von Eurem 'Schlangengift' betroffen sind, (33.4% der Angriffskraft) zusätzlichen Feuerschaden zu. Belegt außerdem bis zu 3 Ziele mit 'Schlangengift'." }
entries[271046] = { ["name"] = "Salzschlag", ["text"] = "Nahkampfreichweite\nWirken in 2.5 sek. 3 sek. Abklingzeit\nDer Zaubernde versprüht in einem frontalen kegelförmigen Bereich von 20 Metern Salz, das allen getroffenen Gegnern Naturschaden und durch verhärtende Ablagerungen 5 Sek. lang zusätzlichen Naturschaden zufügt." }
entries[271047] = { ["name"] = "Instabile Bombe", ["text"] = "100 Meter Reichweite\nSofort\nSchleudert eine Bombe auf das Ziel, die bei der Explosion in einem kegelförmigen Bereich (78% der Angriffskraft) Feuerschaden verursacht und Gegner mit unbeständigem Lauffeuer bedeckt, das ihnen im Verlauf von 6 Sek. (156% der Angriffskraft) Feuerschaden zufügt. Fügt Zielen über 8 Ziele hinaus verringerten Schaden zu.\n\nFügt Eurem Primärziel 80% mehr Schaden zu.\n\n'Instabile Bombe' reagiert heftig mit Gift und fügt so Zielen, die von Eurem 'Schlangengift' betroffen sind, (33.4% der Angriffskraft) zusätzlichen Feuerschaden zu. Belegt außerdem bis zu 3 Ziele mit 'Schlangengift'." }
entries[271048] = { ["name"] = "Instabile Bombe", ["text"] = "Unbegrenzte Reichweite\nSofort\nSchleudert eine Bombe auf das Ziel, die bei der Explosion in einem kegelförmigen Bereich (78% der Angriffskraft) Feuerschaden verursacht und Gegner mit unbeständigem Lauffeuer bedeckt, das ihnen im Verlauf von 6 Sek. (156% der Angriffskraft) Feuerschaden zufügt. Fügt Zielen über 8 Ziele hinaus verringerten Schaden zu.\n\nFügt Eurem Primärziel 80% mehr Schaden zu.\n\n'Instabile Bombe' reagiert heftig mit Gift und fügt so Zielen, die von Eurem 'Schlangengift' betroffen sind, (33.4% der Angriffskraft) zusätzlichen Feuerschaden zu. Belegt außerdem bis zu 3 Ziele mit 'Schlangengift'." }
entries[271049] = { ["name"] = "Instabile Bombe", ["text"] = "Unbegrenzte Reichweite\nSofort\nSchleudert eine Bombe auf das Ziel, die bei der Explosion in einem kegelförmigen Bereich (78% der Angriffskraft) Feuerschaden verursacht und Gegner mit unbeständigem Lauffeuer bedeckt, das ihnen im Verlauf von 6 Sek. (156% der Angriffskraft) Feuerschaden zufügt. Fügt Zielen über 8 Ziele hinaus verringerten Schaden zu.\n\nFügt Eurem Primärziel 80% mehr Schaden zu.\n\n'Instabile Bombe' reagiert heftig mit Gift und fügt so Zielen, die von Eurem 'Schlangengift' betroffen sind, (33.4% der Angriffskraft) zusätzlichen Feuerschaden zu. Belegt außerdem bis zu 3 Ziele mit 'Schlangengift'." }
entries[271050] = { ["name"] = "Instabile Bombe", ["text"] = "Sofort\nVersetzt Eure Lauffeuerbombe mit zusätzlichen Reagenzien, die ihr mit jedem Wurf zufällig eine der folgenden Verstärkungen verleihen:\n\nSchrapnellbombe: Schrapnellfragmente durchbohren die Ziele, wodurch [ Mungobiss : 'Mungobiss' / 'Raptorstoß'] und [ Schlachten : 'Schlachten' / 'Zerlegen'] für 9 Sek. eine Blutung hervorrufen, die bis zu 3-mal stapelbar ist.\n\nPheromonbombe: Es besteht eine Chance von 100%, dass die Abklingzeit von 'Tötungsbefehl' abgeschlossen wird, wenn die Fähigkeit gegen ein mit Pheromonen bedecktes Ziel eingesetzt wird.\n\nInstabile Bombe: Reagiert heftig mit Gift und fügt so Zielen, die von Eurem 'Schlangengift' betroffen sind, (33.4% der Angriffskraft) zusätzlichen Feuerschaden zu. Belegt außerdem bis zu 3 Ziele mit 'Schlangengift'." }
